type DateComponents = {
  fullYear?: number;
  month?: number;
  date?: number;
  hours?: number;
  minutes?: number;
  seconds?: number;
  milliSeconds?: number;
};

type DateTokenParser = {
  token: 'd' | 'D' | 'l' | 'j' | 'J' | 'w' | 'W' | 'F' | 'm' | 'n' | 'M' | 'U' | 'y' | 'Y' | 'Z';
  regex: RegExp;
  // eslint-disable-next-line no-unused-vars
  parse: (match: string, existingComponents: DateComponents) => DateComponents;
  order: number;
};

const MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];
const WEEK_DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'] as const;

const dateTokenParsers: DateTokenParser[] = [
  {
    token: 'U', // unix timestamp (seconds)
    regex: /\d+/,
    parse: (match) => {
      const date = new Date(Number(match) * 1000);
      return {
        fullYear: date.getFullYear(),
        month: date.getMonth(),
        date: date.getDate(),
        hours: date.getHours(),
        minutes: date.getMinutes(),
        seconds: date.getSeconds(),
      };
    },
    order: 1,
  },
  {
    token: 'Z', // ISO date string (UTC only)
    regex: /\d{4}-[01]\d-[0-3]\dT[012]\d:[0-5]\d:[0-5]\d\.\d{3}Z/,
    parse: (match) => {
      const subMatchResult = match.match(/(\d{4})-([01]\d)-([0-3]\d)T([012]\d):([0-5]\d):([0-5]\d)\.(\d{3})Z/);
      if (!subMatchResult) return {};
      const [fullYear, month, date, hours, minutes, seconds, ms] = subMatchResult.slice(1).map(Number);
      const utcDate = new Date(Date.UTC(fullYear, month - 1, date, hours, minutes, seconds, ms));
      if (utcDate.getUTCFullYear() !== fullYear) {
        utcDate.setUTCFullYear(fullYear);
      }
      return {
        fullYear: utcDate.getFullYear(),
        month: utcDate.getMonth(),
        date: utcDate.getDate(),
        hours: utcDate.getHours(),
        minutes: utcDate.getMinutes(),
        seconds: utcDate.getSeconds(),
        milliSeconds: utcDate.getMilliseconds(),
      };
    },
    order: 1,
  },
  {
    token: 'd', // two-digit date
    regex: /[0123]\d/,
    parse: (match) => ({
      date: Number(match),
    }),
    order: 2,
  },
  {
    token: 'j', // one/two-digit date
    regex: /[0123]?\d/,
    parse: (match) => ({
      date: Number(match),
    }),
    order: 2,
  },
  {
    token: 'J', // 1st, 2nd, 3rd etc.
    regex: /[123]?\d(?:st|nd|rd|th)/,
    parse: (match) => ({
      date: Number(match.replace(/st|nd|rd|th/, '')),
    }),
    order: 2,
  },
  {
    token: 'm', // two-digit month
    regex: /[01]\d/,
    parse: (match) => ({
      month: Number(match) - 1,
    }),
    order: 2,
  },
  {
    token: 'n', // one/two-digit month
    regex: /[01]?\d/,
    parse: (match) => ({
      month: Number(match) - 1,
    }),
    order: 2,
  },
  {
    token: 'F', // full-text month
    regex: new RegExp(MONTHS.join('|')),
    parse: (match) => {
      const month = MONTHS.indexOf(match);
      return {
        month: month >= 0 ? month : undefined,
      };
    },
    order: 2,
  },
  {
    token: 'M', // short-text month
    regex: new RegExp(MONTHS.map((month) => month.slice(0, 3)).join('|')),
    parse: (match) => {
      const month = MONTHS.map((month) => month.slice(0, 3)).indexOf(match);
      return {
        month: month >= 0 ? month : undefined,
      };
    },
    order: 2,
  },
  {
    token: 'Y', // four-digit year
    regex: /\d{4}/,
    parse: (match) => ({
      fullYear: Number(match),
    }),
    order: 2,
  },
  {
    token: 'y', // two-digit year = 20xx in flatpickr
    regex: /\d{2}/,
    parse: (match) => ({
      fullYear: Number(match) + 2000,
    }),
    order: 2,
  },
  {
    token: 'W', // one/two-digit week number
    regex: /\d{1,2}/,
    parse: (match, { fullYear, month, date }) => {
      if (fullYear === undefined || month !== undefined || date !== undefined) return {}; // skip if date is already known or year is not known

      const targetWeekNo = Number(match);

      // start with Thursday in the week that contains the first day of the year
      const firstDayOfTheYear = new Date(fullYear, 0, 1);
      const result = getDayOfTheSameWeek(firstDayOfTheYear, 'Thursday');

      // shift date to target week
      const dateWeekNo = result.getFullYear() < fullYear ? 0 : 1;
      const weekDiff = targetWeekNo - dateWeekNo;
      result.setDate(result.getDate() + weekDiff * 7);

      return {
        date: result.getDate(),
        month: result.getMonth(),
        fullYear,
      };
    },
    order: 3,
  },
  {
    token: 'l', // full-length day of week
    regex: new RegExp(WEEK_DAYS.join('|')),
    parse: () => ({}),
    order: 3,
  },
  {
    token: 'D', // short-length day of week
    regex: new RegExp(WEEK_DAYS.map((weekDay) => weekDay.slice(0, 3)).join('|')),
    parse: () => ({}),
    order: 3,
  },
  {
    token: 'w', // numeric day of week
    regex: /[0-6]/,
    parse: () => ({}),
    order: 3,
  },
];

const appendRegex = (existingRegex: RegExp, appendedRegex: RegExp, captured: boolean): RegExp =>
  new RegExp(existingRegex.source + (captured ? '(' : '') + appendedRegex.source + (captured ? ')' : ''));

const convertFormatToRegex = (
  format: string
): {
  regex: RegExp;
  captureGroups: {
    index: number;
    parser: DateTokenParser;
  }[];
} => {
  let regex = /(?:)/;
  const captureGroups: ReturnType<typeof convertFormatToRegex>['captureGroups'] = [];

  let currentCaptureGroupIndex = 0;
  let currentEscaped = false;

  format.split('').forEach((char) => {
    if (!currentEscaped) {
      if (char === '\\') {
        currentEscaped = true;
        return;
      }
      const tokenParser = dateTokenParsers.find(({ token }) => char === token);
      if (tokenParser) {
        regex = appendRegex(regex, tokenParser.regex, true);
        captureGroups.push({
          index: ++currentCaptureGroupIndex,
          parser: tokenParser,
        });
        return;
      }
    }

    const escapedChar = ['.', '^', '$', '|', '+', '*', '?', '(', ')', '[', ']', '{', '}', '\\'].includes(char)
      ? `\\${char}`
      : char;
    regex = appendRegex(regex, new RegExp(escapedChar), false);
    currentEscaped = false;
  });

  return { regex, captureGroups };
};

/**
 * parses a date string to a Date object using flatpickr's date format tokens as defined here:
 * https://flatpickr.js.org/formatting/#date-formatting-tokens
 *
 * @param dateString the string to be parsed, e.g. "3/12/14"
 * @param format the flatpickr date format to parse the date string with, e.g. "n/j/y". Characters can be escaped with "\\"
 * @returns
 * - `null` if the date string could not be parsed with the given format
 * - parsed `Date` object otherwise, with time set to 0:00:00 for the current time zone. If only year and week number are included in the date format, the resulting date is the Thursday of that week
 */
export const parseFlatpickrDate = (dateString: string, format: string): Date | null => {
  if (dateString === undefined || dateString === null || format === undefined || format === null) return null;

  if (format === 'd.m.Y') {
    const split = dateString.split('.');
    if (split.length === 3) {
      dateString = `${split[0].padStart(2, '0')}.${split[1].padStart(2, '0')}.${split[2]}`;
    }
  } else if (format === 'Y-m-d') {
    const split = dateString.split('-');
    if (split.length === 3) {
      dateString = `${split[0]}-${split[1].padStart(2, '0')}-${split[2].padStart(2, '0')}`;
    }
  }

  const { regex, captureGroups } = convertFormatToRegex(format);

  const matchResult = dateString.match(regex);
  if (!matchResult) return null;

  let parsedDateComponents: DateComponents = {};
  captureGroups
    .sort((group1, group2) => group1.parser.order - group2.parser.order)
    .forEach((group) => {
      parsedDateComponents = {
        ...group.parser.parse(matchResult[group.index], parsedDateComponents),
        ...parsedDateComponents,
      };
    });

  const result = new Date(
    parsedDateComponents.fullYear ?? new Date().getFullYear(),
    parsedDateComponents.month ?? 0,
    parsedDateComponents.date ?? 1,
    parsedDateComponents.hours ?? 0,
    parsedDateComponents.minutes ?? 0,
    parsedDateComponents.seconds ?? 0,
    parsedDateComponents.milliSeconds ?? 0
  );

  // fix Date constructor treating years from 00-99 as 1900-1999
  if (parsedDateComponents.fullYear !== undefined && parsedDateComponents.fullYear !== result.getFullYear()) {
    result.setFullYear(result.getFullYear() - 1900);
  }

  return result;
};

/**
 * returns the given week day in the same week as the given date - the week starts on Monday
 * @param date some date
 * @param weekDay target day of the week
 * @returns a new `Date` object set to the desired week day in the same week as the given date - the time components are unchanged
 */
export const getDayOfTheSameWeek = (date: Date, weekDay: (typeof WEEK_DAYS)[number]): Date => {
  // shift weekday by 1 to get Monday = 0, Tuesday = 1 etc.
  const shiftWeekDayBy1 = (weekDay: number) => (weekDay - 1 + 7) % 7;

  const targetWeekDay = WEEK_DAYS.indexOf(weekDay);
  const diffToTargetDay = targetWeekDay >= 0 ? shiftWeekDayBy1(targetWeekDay) - shiftWeekDayBy1(date.getDay()) : 0;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + diffToTargetDay);
};
