/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, h, Host, Listen, Method, Prop, State, Watch } from '@stencil/core';
import flatpickr from 'flatpickr';
import FlatpickrLanguages from 'flatpickr/dist/l10n';
import weekSelect from 'flatpickr/dist/plugins/weekSelect/weekSelect';
import { DayElement, Instance } from 'flatpickr/dist/types/instance';
import { CustomLocale } from 'flatpickr/dist/types/locale';
import { DatePickerInvalid, DatepickerMode, FormDataEvent, FormSize, Severity, ValidationState } from '../../types';
import { getDayOfTheSameWeek, parseFlatpickrDate } from '../../utils/date-format-helper';

/**
 * @nativeEvent change - dispatched when date has changed => 'event.target.value' delivers the new date value, format:
 * <br>- in single mode: Y-m-d, e.g. 2022-02-20
 * <br>- in range mode: Y-m-d:Y-m-d, e.g. 2022-02-20:2022-02-21
 * <br>- in week mode: Y-\WW, e.g. 2022-W22
 * @nativeEvent click  - dispatched when date picker was clicked => 'event.target.value' delivers the current date value
 * @nativeEvent invalid  - dispatched when the value is invalid => 'event.detail.reasons' delivers the reason
 *
 * @slot description - named slot 'description', here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 */

@Component({
  tag: 'groupui-date-picker',
  styleUrl: 'date-picker.scss',
  shadow: { delegatesFocus: true },
})
export class DatePicker {
  /**
   * severity of the input
   */
  @Prop({ reflect: true, mutable: true }) severity: Severity = 'none';

  /**
   * value of the date - format:
   * <br>- in single mode: Y-m-d, e.g. 2022-02-20
   * <br>- in range mode: Y-m-d:Y-m-d, e.g. 2022-02-20:2022-02-21
   * <br>- in week mode: Y-\WW, e.g. 2022-W22
   */
  @Prop({ reflect: true, mutable: true }) value: string;

  /**
   * name of the input element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * sets the size of the input field
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  /**
   * disable internal validation
   */
  @Prop({ reflect: true }) readonly noValidation: boolean = false;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * specifies that a date must be selected before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * sets datepicker to readonly
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * displays week numbers
   */
  @Prop({ reflect: true }) readonly weekNumbers: boolean;

  /**
   * range separator between two dates. relevant in range mode. overwrites language default.
   */
  @Prop({ reflect: true }) readonly rangeSeparator: string;

  /**
   * locale to use. i.e. 'de', 'en', 'fr' - list of supported locales:
   * https://github.com/flatpickr/flatpickr/tree/master/src/l10n
   * (overwrites browser language)
   */
  @Prop({ reflect: true }) readonly locale: string;

  /**
   * date format used for the input field
   * <br>- for single/range mode: e.g. j.n.Y => 6.2.2022 (default)
   * <br>- for week mode: e.g. Y-\WW => 2022-W22 (default)
   * <br>check https://flatpickr.js.org/formatting/#date-formatting-tokens for available formats
   */
  @Prop({ reflect: true }) readonly dateFormat: string;

  /**
   * placeholder of the date picker
   */
  @Prop({ reflect: true }) readonly placeholder: string;

  /**
   * make weekends unselectable - not recommended with mode="range", no effect with mode="week"
   */
  @Prop({ reflect: true }) readonly disableWeekends: boolean;

  /**
   * minimum date that a user can pick from (inclusive). The date format must be the same as the value format, i.e.
   * <br>Y-m-d for single and range mode, e.g. 2022-02-06
   * <br>Y-\WW for week mode, e.g. 2022-W26
   */
  @Prop({ reflect: true }) readonly minDate: string;

  /**
   * maximum date that a user can pick to (inclusive). The date format must be the same as the value format, i.e.
   * <br>Y-m-d for single and range mode, e.g. 2022-02-06
   * <br>Y-\WW for week mode, e.g. 2022-W26
   */
  @Prop({ reflect: true }) readonly maxDate: string;

  /**
   * shows status icon on severity danger, warning, success
   */
  @Prop({ reflect: true }) readonly showStatusIcon: boolean = false;

  /**
   * shows the description only when the component has focus
   */
  @Prop({ reflect: true }) readonly descriptionOnlyOnFocus: boolean = false;

  /**
   * set the position of the calendar popup. In the format of "[vertical] [horizontal]". Vertical can be auto, above or below (required). Horizontal can be left, center or right. (optional)
   */
  @Prop({ reflect: true }) readonly position: string = 'auto';

  /**
   * set DatePicker mode to single selection, date range selection or week selection - values: 'single', 'range', 'week'
   */
  @Prop({ reflect: true }) readonly mode: DatepickerMode = 'single';

  /**
   * shows the clear icon when value was entered
   */
  @Prop({ reflect: true }) readonly showClearIcon: boolean = false;

  /**
   * disable manual input of dates, e.g. the date must be selected from the picker
   */
  @Prop({ reflect: true }) readonly disableManualInput: boolean = false;

  /**
   * When set to true, the date-picker popover will always be visible.
   */
  @Prop({ reflect: true }) readonly alwaysOpen: boolean = false;

  /**
   * ARIA label for the clear icon.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-clear-icon' }) readonly a11yLabelClearIcon: string = 'Clear';

  /**
   * ARIA label for the calendar icon.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-calendar-icon' }) readonly a11yLabelCalendarIcon: string = 'Calendar';

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * for react user only - is dispatched when the value is invalid
   */
  @Event({ bubbles: false }) groupuiInvalid: EventEmitter<DatePickerInvalid>;

  /**
   * is dispatched when the datepicker will be opened
   */
  @Event({ bubbles: false }) open: EventEmitter<void>;

  /**
   * is dispatched when the datepicker will be closed
   */
  @Event({ bubbles: false }) close: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * dispatched on month changed. The event details contain the new month as number (0 = January, 11 = December)
   */
  @Event({ bubbles: false }) groupuiOnMonthChanged: EventEmitter<{ month: number }>;

  /**
   * dispatched on year changed. The event details contain the new year as number (e.g. 2024)
   */
  @Event({ bubbles: false }) groupuiOnYearChanged: EventEmitter<{ year: number }>;

  /**
   * is dispatched if the clear icon is clicked
   */
  @Event({ bubbles: false }) groupuiClearClicked: EventEmitter<void>;

  @State() validationState: ValidationState = { isValid: true } as ValidationState;
  @State() internalValue: string = null;
  @State() hasFocus: boolean;
  @State() eventDates: string[] = [];
  @State() disabledDates: Date[] = [];

  @Element() host: HTMLElement;

  private internalDateFormat = 'Y-m-d';
  private internalWeekFormat = 'Y-\\WW';
  private customDateFormat = 'j.n.Y';

  private container: HTMLElement;
  private inputWrapper: HTMLDivElement;
  private flatpickr: Instance = null;

  componentWillLoad() {
    if (!this.value) {
      return;
    }
    this.setInternalValue();
  }

  private setInternalValue(): void {
    if (this.isWeekMode()) {
      try {
        this.internalValue = flatpickr.formatDate(
          parseFlatpickrDate(this.value, this.internalWeekFormat),
          this.internalDateFormat
        );
      } catch (e) {
        this.validationState = { isValid: false, reasons: ['Given value is not a valid week'] };
      }
    } else {
      this.internalValue = this.value;
    }
  }

  componentDidLoad() {
    this.setCustomDateFormat();
    this.initFlatpickr();
    this.addFormsHandling();
    this.validity = this.getValidity();
    this.groupuiDidLoad.emit();
  }

  @Listen('blur')
  onBlur() {
    this.hasFocus = false;
    if (!this.noValidation) {
      this.validateDatePicker({ force: true });
    }
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Enter') {
      this.getInputElement().dispatchEvent(new window.Event('blur', { bubbles: true }));
      event.preventDefault();
    }
    if (event.code === 'Escape') {
      this.flatpickr.close();
      event.preventDefault();
    }
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  @Listen('focus')
  onFocus() {
    this.hasFocus = true;
  }

  @Watch('dateFormat')
  onDateFormatConfigChange() {
    this.setCustomDateFormat();
    this.reinitFlatpickr();
  }

  @Watch('mode')
  @Watch('locale')
  @Watch('rangeSeparator')
  @Watch('disableWeekends')
  @Watch('disableManualInput')
  @Watch('weekNumbers')
  @Watch('position')
  @Watch('minDate')
  @Watch('maxDate')
  @Watch('alwaysOpen')
  onConfigChange() {
    this.reinitFlatpickr();
  }

  private reinitFlatpickr() {
    let savedValue: string;
    if (this.severity === 'danger') {
      savedValue = this.value;
      this.value = null;
    }
    this.initFlatpickr();
    if (savedValue) {
      this.value = savedValue;
      savedValue = null;
    }
  }

  @Watch('internalValue')
  watchInternalValueChange(): void {
    if (!this.flatpickr) {
      return;
    }

    this.validateDatePicker();
    if (!this.validationState.isValid) {
      this.value = this.internalValue;
      this.setRangeDateToInput();
      if (!this.getInputElement().value) {
        this.getInputElement().value = this.getFormattedValue(this.internalValue);
      }
      return;
    }
    this.flatpickr.setDate(this.internalValue != null ? this.getFlatPickrDate() : null, false, this.internalDateFormat);
    this.updateValidValue();
  }

  @Watch('value')
  watchValueChange(): void {
    if (!this.isInternalValueEqualToValue()) {
      this.setInternalValue();
    }
  }

  @Watch('disabled')
  watchDisabledChange(): void {
    // set disabled prop to altInput field from flatpickr
    this.getInputElement()?.setAttribute('disabled', `${this.disabled}`);
  }

  @Watch('severity')
  watchSeverityChange(): void {
    // set severity prop to altInput field from flatpickr
    this.getInputElement()?.setAttribute('severity', this.severity);
  }

  @Watch('validationState')
  onValidationStateChange() {
    this.validity = this.getValidity();
    if (this.validationState.isValid === false) {
      this.severity = 'danger';
      this.host.dispatchEvent(
        new CustomEvent('invalid', {
          detail: {
            reasons: this.validationState.reasons,
          },
        })
      );
      this.groupuiInvalid.emit({
        reasons: this.validationState.reasons,
      });
    } else {
      this.severity = 'none';
    }
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    const inputValue = this.getInputElement().value;
    const convertedDate = this.convertCustomToInternalFormat(inputValue);
    if (convertedDate) {
      // when the date can be converted to the internal format, we mimic an actual date change, by setting the internal value
      this.internalValue = convertedDate;
    } else {
      // if the input value cannot be converted to a valid internal date, we set the `value` and mimic a programmatic value change
      this.value = inputValue;
    }
    // no matter the date conversion result, we must trigger a forced validation in case the user disabled automatic validation
    if (this.noValidation) {
      this.validateDatePicker({ force: true });
    }
  }

  /**
   * This function takes a string, parses it to a date object using the `customDateFormat` and formats it to the `internalDateFormat`.
   *
   * @example The user enters '20.02.2022' into the input field. The function will parse this string to a date object and format it to '2022-02-20'.
   * This happens automatically if we change the date using the datepicker.
   *
   * @param dateString input date string
   * @returns internal date string
   */
  private convertCustomToInternalFormat(dateString: string): string {
    if (this.isRangeMode()) {
      const [fromDate, toDate] = dateString.split(this.getRangeSeparator());
      const parsedFromDate = parseFlatpickrDate(fromDate, this.customDateFormat);
      const parsedToDate = parseFlatpickrDate(toDate, this.customDateFormat);
      if (parsedFromDate && parsedToDate) {
        return `${this.flatpickr.formatDate(parsedFromDate, this.internalDateFormat)}:${this.flatpickr.formatDate(parsedToDate, this.internalDateFormat)}`;
      }
    } else if (this.isWeekMode()) {
      const parsedDate = parseFlatpickrDate(dateString, this.customDateFormat);
      return this.flatpickr.formatDate(parsedDate, this.internalWeekFormat);
    } else {
      const parsedDate = parseFlatpickrDate(dateString, this.customDateFormat);
      if (parsedDate) {
        return this.flatpickr.formatDate(parsedDate, this.internalDateFormat);
      }
    }
  }

  /**
   * sets dates that should be marked as events in the calendar - not possible in week mode
   * <br>Example: await document.querySelector('groupui-date-picker').setEventDates([new Date(2025, 0, 1), new Date(2025, 11, 24)]);
   */
  @Method()
  async setEventDates(dates: Date[]) {
    this.eventDates = dates.map((date) => this.flatpickr.formatDate(date, this.flatpickr.config.ariaDateFormat));
    this.flatpickr.redraw();
  }

  /**
   * sets dates that should be disabled in the calendar - not possible in week or range mode
   * <br>Example: await document.querySelector('groupui-date-picker').setDisabledDates([new Date(2025, 0, 1), new Date(2025, 11, 24)]);
   */
  @Method()
  async setDisabledDates(dates: Date[]) {
    this.disabledDates = dates;
    this.reinitFlatpickr();
  }

  private updateValidValue(): void {
    if (!this.isInternalValueEqualToValue()) {
      if (this.isWeekMode() && this.internalValue != null) {
        this.value = this.flatpickr.formatDate(new Date(this.internalValue), this.internalWeekFormat);
      } else {
        this.value = this.internalValue;
      }
    }

    if (this.isRangeMode() && this.flatpickr.selectedDates.length < 2) {
      return;
    }

    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit();
  }

  /**
   * Returns the given value, formatted with the date format to be displayed by the date picker. If the value is invalid, it will be returned as is.
   * @param value - input value
   * @returns formatted value that is displayed to the user
   */
  private getFormattedValue(value: string): string {
    const parsedDate = parseFlatpickrDate(value, this.internalDateFormat);
    return parsedDate ? this.flatpickr.formatDate(parsedDate, this.customDateFormat) : value;
  }

  private isInternalValueEqualToValue() {
    return this.isWeekMode()
      ? this.value === this.flatpickr.formatDate(new Date(this.internalValue), this.internalWeekFormat)
      : this.value === this.internalValue;
  }

  /**
   * Validates the selected date in the date picker, updating the validation state accordingly.
   * @param {boolean} [options.force=false] - Whether to force the validation even if `noValidation` is true.
   * @returns {void}
   */
  private validateDatePicker({ force = false }: { force?: boolean } = {}) {
    // If noValidation is true and force is false, skip the validation
    if (!force && this.noValidation) {
      return;
    }
    // Parse the internalValue as a date using the internalDateFormat
    // If the parsed date is not valid, set the validation state to invalid with a reason
    const isValidDate = !this.isValueSet() || parseFlatpickrDate(this.internalValue, this.internalDateFormat);
    if (!isValidDate) {
      this.validationState = { isValid: false, reasons: ['Given value is not a valid Date'] };
      return;
    }
    // Validate other constraints (Min/Max, Weekends, Required)
    const validationErrors = [];
    if (!this.isInternalDateInMinMax()) {
      validationErrors.push('Chosen date is not in min/max range');
    }
    if (this.required && !this.isValueSet()) {
      validationErrors.push('Chosen date is required');
    }
    if (!this.isInternalDateValidForWeekendSettings()) {
      validationErrors.push('Chosen date is on a weekend');
    }
    // If there are any validation errors, set the validation state to invalid with the error messages. This will the validation state change.
    if (validationErrors.length > 0) {
      this.validationState = { isValid: false, reasons: validationErrors };
    } else {
      // Otherwise, set the validation state to valid
      this.validationState = { isValid: true };
    }
  }

  /**
   *
   * @returns {ValidityState} - The validity state of the date picker according to native html validity state
   */
  private getValidity() {
    const badInput = !parseFlatpickrDate(this.internalValue, this.internalDateFormat);
    const valueMissing = this.required && !this.isValueSet();
    const customError = !this.isInternalDateInMinMax() || !this.isInternalDateValidForWeekendSettings();
    return {
      valid: !badInput && !valueMissing && !customError,
      customError,
      valueMissing,
      badInput: !!badInput,
      rangeOverflow: false,
      rangeUnderflow: false,
      stepMismatch: false,
      tooLong: false,
      tooShort: false,
      typeMismatch: false,
      patternMismatch: false,
    };
  }

  private getInputElement(): HTMLInputElement {
    return this.host.shadowRoot.querySelector('.date-picker-input');
  }

  private toggleFlatpickrVisibility = (e) => {
    e.stopPropagation();
    if (this.flatpickr.isOpen) {
      this.flatpickr.close();
    } else {
      this.flatpickr.open();
    }
  };

  private initInputField() {
    const datepickerInput = this.getInputElement();
    if (datepickerInput) {
      datepickerInput.setAttribute('severity', this.severity);
      datepickerInput.setAttribute('size', this.size);
      datepickerInput.setAttribute('role', 'combobox');
      datepickerInput.setAttribute('aria-expanded', this.flatpickr?.isOpen ? 'true' : 'false');
      datepickerInput.setAttribute('no-validation', 'true');
      this.getAriaLabelForInternalInput() &&
        datepickerInput.setAttribute('aria-label', this.getAriaLabelForInternalInput());
      this.getAriaDescriptionForInternalInput() &&
        datepickerInput.setAttribute('aria-description', this.getAriaDescriptionForInternalInput());
      if (this.disableManualInput) {
        datepickerInput.addEventListener('focus', () => this.flatpickr.open());
        datepickerInput.addEventListener('mousedown', this.toggleFlatpickrVisibility);
      }
    }
  }

  private getAriaLabelForInternalInput(): string {
    if (this.host.getAttribute('aria-label') !== null) {
      return this.host.getAttribute('aria-label');
    }
    if (this.isLabelSlotProvided()) {
      return this.getSlotContent('label');
    }
    return undefined;
  }

  private getAriaDescriptionForInternalInput(): string {
    if (this.host.getAttribute('aria-description') !== null) {
      return this.host.getAttribute('aria-description');
    }
    if (this.isDescriptionSlotProvided()) {
      return this.getSlotContent('description');
    }
    return undefined;
  }

  private getSlotContent(slotName: string): string {
    const slot = this.host.querySelector(`[slot="${slotName}"]`);
    return slot.innerHTML;
  }

  private addFormsHandling() {
    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, this.value);
    });

    form.addEventListener('submit', (event: FormDataEvent) => {
      this.validateDatePicker();
      if (!this.validationState.isValid) {
        event.preventDefault();
      }
    });
  }

  private onClose = () => {
    this.getInternalInputElement().setAttribute('aria-expanded', 'false');
    this.close.emit();
  };

  private onChange = (values: Date[]) => {
    // we only reach this code if the user has selected the value manually
    this.removeTextSelection();
    if (values.some((value) => !this.isValidDate(value))) {
      return;
    }
    if (this.isWeekMode() && values.length > 0) {
      // For dates around Dec 31st/Jan 1st, it's possible that the date's year is not the same as the calendar week's year.
      // To prevent issues with that, the internal value for selected weeks is set to the week's Thursday.
      // Thursdays are by definition always in the same year as their calendar week.
      const selectedDate = values[0];
      this.internalValue = this.flatpickr.formatDate(
        getDayOfTheSameWeek(selectedDate, 'Thursday'),
        this.internalDateFormat
      );
    } else {
      this.internalValue = values.map((date) => this.flatpickr.formatDate(date, this.internalDateFormat)).join(':');
    }
  };

  private isValueSet() {
    return this.internalValue !== undefined && this.internalValue !== null && this.internalValue.length > 0;
  }

  private getFlatPickrDate(): string | string[] {
    if (this.internalValue?.includes(':')) {
      return this.internalValue.split(':');
    }
    return this.internalValue;
  }

  private isInternalDateInMinMax() {
    if (!this.isValueSet()) return true;
    if (this.internalValue.includes(':')) {
      const values = this.internalValue.split(':');
      const fromDate = values[0];
      const toDate = values[1];

      const isFromValid = this.isDateStringInMinMax(fromDate);
      const isToValid = this.isDateStringInMinMax(toDate);

      return isFromValid && isToValid;
    } else {
      return this.isDateStringInMinMax(this.internalValue);
    }
  }

  /**
   * Checks if the selected date(s) are on a weekend, taking into account the `disableWeekends` setting.
   * @returns {boolean} Whether the selected date(s) are not on a weekend.
   */
  private isInternalDateValidForWeekendSettings() {
    if (this.isWeekMode() || !this.disableWeekends) return true;
    if (!this.isValueSet()) return true;
    if (this.internalValue.includes(':')) {
      const values = this.internalValue.split(':');
      const fromDate = values[0];
      const toDate = values[1];

      const isFromDateOnWeekend = this.isDateOnWeekend(new Date(fromDate));
      const isToDateOnWeekend = this.isDateOnWeekend(new Date(toDate));

      return !isFromDateOnWeekend && !isToDateOnWeekend;
    } else {
      return !this.isDateOnWeekend(new Date(this.internalValue));
    }
  }

  private isDateStringInMinMax(internalDateString: string) {
    let isValid = true;
    const minDateObject = this.getMinDate();
    const maxDateObject = this.getMaxDate();
    const dateObject = parseFlatpickrDate(internalDateString, this.internalDateFormat);

    if (minDateObject) {
      isValid = isValid && this.isValidDate(minDateObject) ? minDateObject <= dateObject : false;
    }

    if (maxDateObject) {
      isValid = isValid && this.isValidDate(maxDateObject) ? maxDateObject >= dateObject : false;
    }

    return isValid;
  }

  private isValidDate(d: Date): d is Date {
    return d instanceof Date;
  }

  private isWeekMode() {
    return this.mode === 'week';
  }

  private isRangeMode() {
    return this.mode === 'range';
  }

  private getFlatpickrMode() {
    return this.isRangeMode() && !this.isWeekMode() ? 'range' : 'single';
  }

  private getMinDate() {
    if (!this.minDate) return null;
    if (this.isWeekMode()) {
      const thursdayOfMinWeek = parseFlatpickrDate(this.minDate, this.internalWeekFormat);
      if (!thursdayOfMinWeek) return null;
      return getDayOfTheSameWeek(thursdayOfMinWeek, 'Monday');
    }
    return parseFlatpickrDate(this.minDate, this.internalDateFormat);
  }

  private getMaxDate() {
    if (!this.maxDate) return null;
    if (this.isWeekMode()) {
      const thursdayOfMaxWeek = parseFlatpickrDate(this.maxDate, this.internalWeekFormat);
      if (!thursdayOfMaxWeek) return null;
      return getDayOfTheSameWeek(thursdayOfMaxWeek, 'Sunday');
    }
    return parseFlatpickrDate(this.maxDate, this.internalDateFormat);
  }

  /**
   * This is a custom date parser for our flatpickr config which helps us to process invalid inputs & prevent flatpickr from logging errors to the console
   */
  private customFlatpickrDateParser(dateString: string, format: string) {
    const parsedDate = parseFlatpickrDate(dateString, format);
    if (parsedDate) {
      return parsedDate;
    }
    // If the date string is invalid, we just set the internal value to the invalid string, so that it can still be displayed
    this.internalValue = dateString;
    return undefined;
  }

  /**
   * This is a custom date formatter for our flatpickr config which allows us to display invalid dates in the input field
   */
  private customFlatpickrDateFormatter(date: Date | undefined, format: string) {
    if (!date) {
      // needed because flatpickr pushes an unguarded undefined item in its selectedDates
      // array which breaks the range-selection, because it sucks
      if (this.isRangeMode()) {
        this.flatpickr.selectedDates = [];
      }
      return this.internalValue;
    }
    if (this.isWeekMode()) {
      // prevents a bug caused by flatpickr not checking if a day belongs to a calendar week of the next/previous year
      return flatpickr.formatDate(getDayOfTheSameWeek(date, 'Thursday'), format);
    }
    return flatpickr.formatDate(date, format);
  }

  private setCustomDateFormat() {
    if (this.dateFormat) {
      this.customDateFormat = this.dateFormat;
    } else if (this.isWeekMode()) {
      this.customDateFormat = this.internalWeekFormat;
    }
  }

  private initFlatpickr() {
    if (!this.inputWrapper) return;

    if (this.flatpickr) {
      this.flatpickr.destroy();
    }

    this.flatpickr = flatpickr(this.inputWrapper, {
      plugins: this.isWeekMode() ? [weekSelect()] : [],
      dateFormat: this.internalDateFormat,
      altFormat: this.customDateFormat,
      altInput: true,
      altInputClass: 'date-picker-input',
      locale: {
        ...this.flatpickrLocale(),
        rangeSeparator: this.getRangeSeparator(),
        firstDayOfWeek: 1,
      },
      inline: this.alwaysOpen,
      monthSelectorType: 'static',
      appendTo: this.container,
      onChange: this.onChange,
      onClose: this.onClose,
      onOpen: this.onOpen,
      onMonthChange: () => {
        this.addEventMarkers();
        this.groupuiOnMonthChanged.emit({ month: this.flatpickr.currentMonth });
      },
      onYearChange: () => {
        this.groupuiOnYearChanged.emit({ year: this.flatpickr.currentYear });
      },
      allowInput: !this.disableManualInput,
      allowInvalidPreload: true,
      static: true,
      minDate: this.getMinDate(),
      maxDate: this.getMaxDate(),
      parseDate: (datestr, format) => this.customFlatpickrDateParser(datestr, format),
      formatDate: (date, format) => this.customFlatpickrDateFormatter(date, format),
      mode: this.getFlatpickrMode(),
      clickOpens: false,
      disable: this.getDisabledDates(),
      weekNumbers: this.weekNumbers,
      wrap: true,
      disableMobile: true,
      positionElement: this.inputWrapper,
      errorHandler: () => {}, // this prevents flatpickr from logging warnings
    });
    const flatpickrRedraw = this.flatpickr.redraw;
    this.flatpickr.redraw = () => {
      flatpickrRedraw();
      this.setRangeDateToInput();
      this.addEventMarkers();
    };
    // This is truly ridiculous! "selectedDateElm" represents the HTLMSpanElement of the selected date in the picker + its row index in the picker-view "$i" (0 = first date row ).
    // When the first date entered in WeekMode is invalid, this property will not be set, but the week-plugin internally tries to access it in order to highlight the week int the picker view.
    // This throws an error and breaks the whole picker. So we set it to a dummy value here to prevent that.
    // reference: weekSelect.js line 46 + 47
    if (this.isWeekMode()) {
      this.flatpickr.selectedDateElem = {
        $i: 0,
      } as DayElement;
    }
    this.flatpickr.setDate(this.getFlatPickrDate(), false, this.internalDateFormat);
    this.initInputField();
  }

  private getDisabledDates() {
    const dates = [];
    if (!this.isWeekMode() && this.disableWeekends) {
      dates.push(this.isDateOnWeekend);
    }
    if (this.isWeekMode() || this.isRangeMode()) return dates;
    return [...dates, ...this.disabledDates];
  }

  private setRangeDateToInput(): void {
    if (this.isRangeMode()) {
      const [fromDate, toDate] = this.internalValue?.split(':') || [];
      if (fromDate && toDate) {
        if (fromDate === toDate) {
          this.getInputElement().value = this.getFormattedValue(fromDate);
        } else {
          this.getInputElement().value =
            this.getFormattedValue(fromDate) + this.getRangeSeparator() + this.getFormattedValue(toDate);
        }
      }
    }
  }

  private isDateOnWeekend(date: Date): boolean {
    return date.getDay() === 0 || date.getDay() === 6;
  }

  /**
   * Updates the position of the date picker element based on the `position` property.
   */
  private updatePickerPosition(): void {
    // Get the date picker and wrapper elements
    const pickerElement = this.host.shadowRoot.querySelector('.flatpickr-calendar') as HTMLElement;
    const pickerWrapperElement = this.host.shadowRoot.querySelector('.flatpickr-wrapper') as HTMLElement;

    // Get the vertical and horizontal position from the `position` property
    const [vertical, horizontal] = this.position.split(' ') as [string, string];

    // Get the dimensions and position of the date picker element and wrapper element
    const { width: pickerElementWidth, height: pickerElementHeight } = pickerElement.getBoundingClientRect();
    const {
      width: pickerWrapperWidth,
      height: pickerWrapperHeight,
      y: pickerWrapperYPosition,
    } = pickerWrapperElement.getBoundingClientRect();

    // Set the offset between the date picker and wrapper elements
    const offset = 8;

    // Update the vertical position of the date picker element
    switch (vertical) {
      case 'above':
        pickerElement.style.bottom = `${pickerWrapperHeight + offset}px`;
        break;
      case 'below':
        pickerElement.style.top = `${pickerWrapperHeight + offset}px`;
        break;
      default:
        pickerElement.style.top = `${this.calculatePickerAutoOffsetY(
          pickerWrapperYPosition,
          pickerWrapperHeight,
          pickerElementHeight,
          offset
        )}px`;
    }

    // Update the horizontal position of the date picker element
    switch (horizontal) {
      case 'right':
        pickerElement.style.right = '0px';
        break;
      case 'center':
        pickerElement.style.left = `${(pickerWrapperWidth - pickerElementWidth) / 2}px`;
        break;
      default:
        pickerElement.style.left = '0px';
    }
  }

  /**
   * Calculates the vertical offset for the date picker element based on its position relative to the window.
   * @param pickerWrapperYPosition The Y position of the date picker wrapper element.
   * @param pickerWrapperHeight The height of the date picker wrapper element.
   * @param pickerElementHeight The height of the date picker element.
   * @param offset The offset between the date picker and wrapper elements.
   * @returns The calculated vertical offset for the date picker element.
   */
  private calculatePickerAutoOffsetY(
    pickerWrapperYPosition: number,
    pickerWrapperHeight: number,
    pickerElementHeight: number,
    offset: number
  ): number {
    const windowHeight = window.innerHeight;
    if (pickerWrapperYPosition + pickerElementHeight + pickerWrapperHeight + offset > windowHeight) {
      return -pickerElementHeight - offset;
    }
    return pickerWrapperHeight + offset;
  }

  private updatePickerDayContainerWidth(): void {
    const pickerDayContainer = this.host.shadowRoot.querySelector('.flatpickr-days') as HTMLElement;
    pickerDayContainer.style.width = '100%';
  }

  private onOpen = () => {
    this.updatePickerPosition();
    // This needs to be done, because flatpickr fails to set
    // the width of the day container correctly if it has initially been
    // rendered in a hidden container (e.g. groupui-tab)
    this.updatePickerDayContainerWidth();
    this.getInternalInputElement().setAttribute('aria-expanded', 'true');
    this.open.emit();
  };

  private getInternalInputElement() {
    return this.getInputElement().shadowRoot.querySelector('input');
  }

  private addEventMarkers = () => {
    if (this.mode !== 'week' && this.eventDates.length > 0) {
      this.host.shadowRoot.querySelectorAll('.flatpickr-day').forEach((day) => {
        if (this.eventDates.includes(day.getAttribute('aria-label'))) {
          day.classList.add('event');
        }
      });
    }
  };

  private static browserLanguage(): string {
    return window.navigator.language?.slice(0, 2);
  }

  private preferredLanguage(): string {
    if (this.locale) return this.locale;
    return DatePicker.browserLanguage();
  }

  private flatpickrLocale(): CustomLocale {
    if (FlatpickrLanguages[this.preferredLanguage()]) return FlatpickrLanguages[this.preferredLanguage()];
    return FlatpickrLanguages.en;
  }

  private getRangeSeparator() {
    return this.rangeSeparator ? this.rangeSeparator : this.flatpickrLocale().rangeSeparator;
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private useStatusIcon() {
    return this.showStatusIcon && this.severity && this.severity !== 'none';
  }

  private getStatusIcon() {
    switch (this.severity) {
      case 'warning':
        return `warning-filled-${this.iconSize()}`;
      case 'danger':
        return `error-filled-${this.iconSize()}`;
      case 'success':
        return `success-filled-${this.iconSize()}`;
    }
  }

  private iconSize() {
    return this.size === 's' ? 16 : 24;
  }

  private showDescription() {
    if (!this.descriptionOnlyOnFocus) {
      return true;
    } else {
      return this.hasFocus;
    }
  }

  private clearInput = (event) => {
    this.value = null;

    // re-init is necessary because flatpickr.clear does not remove the week selection within the calendar.
    this.isWeekMode() && this.initFlatpickr();

    this.groupuiClearClicked.emit();
    event.preventDefault();
  };

  private isClearIconVisible() {
    return this.value && !this.disabled && this.showClearIcon;
  }

  private removeTextSelection() {
    // this fixes a weird behavior in Edge, where a non-visible text is marked/selected and an annoying context menu is shown - unfortunately not testable
    window.getSelection().removeAllRanges();
  }

  render() {
    return (
      <Host data-show-clear-icon={String(this.isClearIconVisible())}>
        <div ref={(el) => (this.container = el)} />
        {this.isLabelSlotProvided() && (
          <label id="label" aria-hidden="true">
            <slot name="label" />
          </label>
        )}
        <div class="input-wrapper flatpickr" ref={(el) => (this.inputWrapper = el)}>
          <groupui-input
            placeholder={this.placeholder}
            id="flatpickr"
            severity={this.severity}
            disabled={this.disabled}
            size={this.size}
            data-input
            no-validation
            style={{ display: 'none' }}
          />
          {this.isClearIconVisible() && (
            <div>
              <groupui-embedded-button
                id="clear"
                icon={`close-${this.iconSize()}`}
                size={this.size === 'm' ? 'xs' : 'xxs'}
                aria-label={this.a11yLabelClearIcon}
                onClick={this.clearInput}
                aria-hidden={true}
              ></groupui-embedded-button>
            </div>
          )}

          {this.useStatusIcon() && (
            // The next div is needed because flatpickr somehow gets confused distinguishing between
            // the toggle calendar icon and the severity icon if it is not placed inside a container.
            // This leads to the calendar not opening in some conditions, so please leave it in.
            <div>
              <groupui-icon
                id="status"
                name={this.getStatusIcon()}
                width={this.iconSize()}
                height={this.iconSize()}
                aria-hidden="true"
                class="status-icon"
              />
            </div>
          )}
          <groupui-embedded-button
            id="calendar"
            class="calendar-icon"
            icon={`calendar-${this.iconSize()}`}
            size={this.size === 'm' ? 'xs' : 'xxs'}
            aria-label={this.a11yLabelCalendarIcon}
            disabled={this.disabled}
            data-toggle={this.disableManualInput ? undefined : true}
            onMouseDown={(ev) => ev.stopPropagation()}
          ></groupui-embedded-button>
        </div>
        {this.isDescriptionSlotProvided() && this.showDescription() && (
          <div id="description" aria-hidden="true">
            <slot name="description" />
          </div>
        )}
      </Host>
    );
  }
}
